/// Loads the line items of each order, with product names.
pub async fn load_order_details(
    pool: &PgPool,
    tracker: &Tracker,
    orders: Vec<OrderRow>,
) -> Result<Vec<OrderView>, sqlx::Error> {
    if orders.is_empty() {
        return Ok(Vec::new());
    }
    // One query for every item of every order on the page, joined with product names.
    let order_ids: Vec<i64> = orders.iter().map(|o| o.id).collect();
    let rows = tracker
        .run(
            sqlx::query(
                "SELECT oi.order_id, oi.product_id, p.name, oi.quantity, oi.unit_price_cents \
                 FROM order_items oi JOIN products p ON p.id = oi.product_id \
                 WHERE oi.order_id = ANY($1) ORDER BY oi.order_id, oi.id",
            )
            .bind(order_ids.as_slice())
            .fetch_all(pool),
        )
        .await?;
    let mut by_order: std::collections::HashMap<i64, Vec<ItemView>> =
        std::collections::HashMap::with_capacity(orders.len());
    for row in rows {
        by_order.entry(row.get("order_id")).or_default().push(ItemView::new(
            row.get("product_id"),
            row.get("name"),
            row.get("quantity"),
            row.get("unit_price_cents"),
        ));
    }
    Ok(orders
        .into_iter()
        .map(|order| {
            let items = by_order.remove(&order.id).unwrap_or_default();
            OrderView::from_parts(order, items)
        })
        .collect())
}
